local function StopRoute(StatusText)
S.Phase = "Idle"
S.ReturnKill = false
S.ReturnMissAt = nil
S.SeenTarget = false
S.LastTarget = nil
S.TargetSeenAt = nil
S.KillAt = nil
S.WaitUntil = nil
S.SpotWaitUntil = nil
S.WalkStart = nil
S.SkipSpotWait = false
S.SkipSpotWaitNext = false
S.TeleportHold = nil
S.OwnDeaths = 0
S.OwnDeathAt = nil
SyncDeathMark()
EndDodge()
StopFlee()
AICCombat.S.ClosestTarget = nil
ResetWalk()
