AICUI.RefreshDeadzonePicker()
AICProfile.SaveActiveProfile()
AICDebug.UpdateDebugVisualizer()
AICUI.SetProfileStatus("DEADZONE REMOVED #" .. tostring(Index))
end
end
return Feature
end,
